/* Intermediate8: cache-aside data correctness plus explicitly bounded managed-cache metadata. */
(function(){
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),wrap=x=>'<div class="tbl-wrap">'+x+'</div><p class="muted">Phone par table sideways swipe karo.</p>';
  function Q(q,correct,wrong,answer,explain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};}
  const ROLE='arn:aws:iam::123456789012:role/cart-dax-read';
  function seed(){return {region:'ap-south-1',vpcs:[{id:'vpc-shop',cidr:'10.216.0.0/16',name:'shop',default:false}],subnets:['a','b','c'].map((az,i)=>({id:'subnet-cache-'+az,vpcId:'vpc-shop',az:'ap-south-1'+az,cidr:'10.216.'+(i+1)+'.0/24',public:false,name:'cache-'+az})),securityGroups:[{id:'sg-app',vpcId:'vpc-shop',name:'catalog-app',ingress:[],egress:[{protocol:'tcp',fromPort:6379,toPort:6379,destinationGroup:'sg-cache'},{protocol:'tcp',fromPort:9111,toPort:9111,destinationGroup:'sg-cache'}]},{id:'sg-cache',vpcId:'vpc-shop',name:'catalog-cache',ingress:[{protocol:'tcp',fromPort:6379,toPort:6379,cidr:'0.0.0.0/0'}],egress:[]}],cacheSubnetGroups:[{name:'shop-cache-private',subnetIds:['subnet-cache-a','subnet-cache-b','subnet-cache-c']}],daxSubnetGroups:[{name:'shop-dax-private',subnetIds:['subnet-cache-a','subnet-cache-b','subnet-cache-c']}],cacheUserGroups:[{id:'catalog-app',engine:'valkey',status:'active',scope:'catalog:shop:*',permissions:['get','set','del','expire']}],roles:[{name:'cart-dax-read',arn:ROLE,daxTrust:'dax.amazonaws.com',daxReadTables:['carts']}],tables:[{name:'carts',tableId:'22222222-2222-4222-8222-222222222222',partitionKey:'cartId',billing:'PAY_PER_REQUEST',items:[{cartId:'cart-101',total:499,version:1}]}],rds:[{id:'shop-orders',name:'shop-orders',engine:'postgres',class:'db.m7g.large',storage:100,port:5432,state:'available',multiAZ:true,endpoint:'shop-orders.local-fixture.rds.amazonaws.com'}],cacheGroups:[],daxClusters:[]};}
  const cache=s=>(s.account.cacheGroups||[]).find(g=>g.id==='catalog-cache');
  function preserve(s){const a=seed();return ['vpcs','subnets','cacheSubnetGroups','daxSubnetGroups','cacheUserGroups','roles','rds'].every(k=>JSON.stringify(s.account[k])===JSON.stringify(a[k]))&&JSON.stringify((s.account.tables||[]).map(t=>({name:t.name,tableId:t.tableId,partitionKey:t.partitionKey,billing:t.billing,items:t.items})))===JSON.stringify(a.tables.map(t=>({name:t.name,tableId:t.tableId,partitionKey:t.partitionKey,billing:t.billing,items:t.items})))&&JSON.stringify(s.account.securityGroups.find(g=>g.id==='sg-app'))===JSON.stringify(a.securityGroups[0]);}
  function privateRule(s,port){const sg=(s.account.securityGroups||[]).find(g=>g.id==='sg-cache');return !!sg&&sg.vpcId==='vpc-shop'&&sg.ingress.length===1&&sg.ingress[0].protocol==='tcp'&&sg.ingress[0].fromPort===port&&sg.ingress[0].toPort===port&&sg.ingress[0].sourceGroup==='sg-app'&&!sg.ingress[0].cidr;}
  function cacheReady(s){const g=cache(s);return !!g&&s.account.cacheGroups.length===1&&(s.account.daxClusters||[]).length===0&&g.status==='available'&&!g.pending&&g.engine==='valkey'&&g.engineVersion==='8.0'&&g.port===6379&&g.nodeType==='cache.t4g.small'&&g.subnetGroup==='shop-cache-private'&&g.vpcId==='vpc-shop'&&g.nodes.length===2&&g.nodes.every(n=>n.status==='available')&&g.nodes.filter(n=>n.role==='primary').length===1&&g.nodes.filter(n=>n.role==='replica').length===1&&new Set(g.nodes.map(n=>n.az)).size===2&&g.nodes.every(n=>['ap-south-1a','ap-south-1b'].includes(n.az));}
  const SOLUTION=[
    'aws ec2 revoke-security-group-ingress --group-id sg-cache --protocol tcp --port 6379 --cidr 0.0.0.0/0',
    'aws ec2 authorize-security-group-ingress --group-id sg-cache --protocol tcp --port 6379 --source-group sg-app',
    "aws elasticache create-replication-group --replication-group-id catalog-cache --replication-group-description 'ShopKaro catalogue cache' --engine valkey --engine-version 8.0 --cache-node-type cache.t4g.small --num-cache-clusters 2 --preferred-cache-cluster-azs ap-south-1a ap-south-1b --cache-subnet-group-name shop-cache-private --security-group-ids sg-cache --transit-encryption-enabled --at-rest-encryption-enabled --user-group-ids catalog-app",
    'aws elasticache wait replication-group-available --replication-group-id catalog-cache',
    'aws elasticache modify-replication-group --replication-group-id catalog-cache --automatic-failover-enabled --multi-az-enabled --apply-immediately',
    'aws elasticache wait replication-group-available --replication-group-id catalog-cache',
    'aws elasticache describe-replication-groups --replication-group-id catalog-cache'
  ];
  const TASKS=[{text:'Original DB/cart data, subnet groups, app SG, RBAC and role metadata preserved',check:preserve},{text:'Only app SG can reach cache port 6379; public rule removed',check:s=>privateRule(s,6379)},{text:'One ready traditional Valkey 8.0 cache: two small nodes, primary+replica in AZ-a/b',check:cacheReady},{text:'Automatic failover + Multi-AZ enabled; transit/at-rest encryption and scoped RBAC attached',check:s=>{const g=cache(s);return !!g&&g.automaticFailover&&g.multiAZ&&g.transitEncryption&&g.atRestEncryption&&g.userGroupIds.length===1&&g.userGroupIds[0]==='catalog-app'&&g.securityGroupIds.length===1&&g.securityGroupIds[0]==='sg-cache';}},{text:'Final current describe returns ready configuration and both actual node/AZ records',check:s=>{const g=cache(s),r=s.cacheRead?.service==='elasticache'&&s.cacheRead.groups.find(r=>r.id==='catalog-cache');return !!g&&!!r&&r.revision===g.revision&&r.record.Status==='available'&&r.record.MemberClusters.length===2&&r.record.NodeGroups[0].NodeGroupMembers.length===2;}}];
  function plan(k){const products=1000,capacity=Math.min(1,k.memory*1024/(products*2*1.5)),perRead=k.reads/products,perWrite=k.writes/products,lifetime=(1-Math.exp(-perWrite*k.ttl))/perWrite,hit=k.key?capacity*(perRead*lifetime)/(1+perRead*lifetime):0,miss=k.reads*(1-hit),db=miss*40,ecpu=(k.reads*2+miss*2+k.writes)*30*86400,serverless=.1*.084*720+ecpu*.0000000023,nodes=2*.0256*720;return {hit,miss,db,capacity,serverless,nodes,burst:k.refill?1:200,ok:k.reads>=1000&&k.writes>=3&&k.ttl<=60&&hit>=.95&&db<=1000&&k.refill===1};}
  AG.registerLevels('intermediate',[{
    id:'caching',icon:'⚡',title:'Caching — correct keys, fresh data aur safe refill',badge:'Cache Chatur',
    objectives:['<b>Why:</b> repeated catalogue queries reduce karo; checkout correctness preserve karo','<b>Strategy:</b> cache-aside, write-through, write-behind and invalidation','<b>Key:</b> response scope, TTL, eviction, negative cache and stampede','<b>Service:</b> Valkey/Redis OSS/Memcached, DAX, MemoryDB and current durability options','<b>Operations:</b> actual nodes/AZs, TLS/RBAC, bounded failures and complete cost','<b>Proof:</b> actual origin calls, stale-fill race and managed metadata limits'],
    hook:{when:'SHOPKARO · MAHASALE PREVIEW · FICTIONAL COURSE STORY',title:'“Ek product page ke 40 queries — DB ko cache chahiye, par stock galat nahi hona chahiye.”',text:'Catalogue page repeat hota hai aur RDS CPU 95% tak pahunchti hai. Ravi read replica add karta hai; asynchronous replica se old stock dikh sakta hai. Neha catalogue cache approve karti hai, par checkout price/stock authoritative DB transaction se confirm honge. Pehle unnecessary N+1 queries fix karo; cache bad query shape aur business correctness ka automatic repair nahi.'},
    steps:[
      {q:'Cache real-world pain kaunsa solve karti hai?',analogy:'Dukaan counter par popular catalogue rakhta hai; har customer ke liye godown se same page nahi mangata. Counter copy fast hai, par stock sale godown ke authoritative ledger mein commit hoti hai.',body:'<p>Cache stores a reusable result close to a caller. Hit returns stored data; miss fetches origin and usually populates cache. Fewer origin reads can lower latency/load, but memory, network, stale data and refill failures add operating cost.</p>',points:['Course catalogue may accept a reviewed 60 s stale window. Checkout stock/price invariants use the authoritative transaction path; cached or asynchronous replica data is not sufficient proof of available stock.','In-process cache is fast but local to each app instance; deployments/scaling lose or duplicate entries. Shared cache centralizes reuse but adds network and shared-failure dependencies. Sessions outside one EC2 instance help load balancing, but session durability/revocation/expiry still need design.','Hit ratio alone is not success. A 99% hit rate serving the wrong tenant or old checkout price is a bug. Measure correct data, origin calls, tail latency, errors and failure fallback under required load.'],asli:'Action: local lab executes actual DynamoDB reads behind a host cache. Ten same-scope catalogue requests produce one origin read and nine hits. This is not an AWS or Valkey latency benchmark.'},
      {q:'Cache key mein kya rakhein; request ID kyun nahi?',analogy:'Shelf label product, tenant aur edition batata hai. Har customer ke receipt number se same public catalogue ka separate shelf banega toh reuse khatam. Personalized quotation ko public shelf par rakhna privacy bug hai.',body:'<p>Key includes every input that changes the cached response: product, tenant, locale/currency, authorization or price scope, schema/version and relevant query options. Exclude request/session timestamps only when those values do not change this response. Never remove tenant/auth scope merely to improve hit ratio.</p>',points:['Catalogue fixture key is JSON tuple [catalog-v1, tenant, product]. Stable encoding avoids ambiguous delimiter collisions. Authorized tenant/scope must come from reviewed app context; the cache helper does not authenticate users.','Same public product read with sessionId/requestTime in the key becomes a new entry per request. Inspect sampled keys, cardinality and hits/misses before increasing node size. Query result caches also need explicit filter/sort/page/version scope.','Serialize deliberately, validate returned tenant/product and return independent copies. Old schema bytes, mutable references, oversized values and unbounded keys can poison cache or exhaust memory. Cache errors must not silently return another user record.'],code:"# Host lab reference; existing adapter fetches the exact tenant/product\ncache = CacheAside(fetch, ttl=60, max_entries=100)\ncache.get('shop', 'kurta')\ncache.invalidate('shop', 'kurta')",asli:'Action: triage inspects a public catalogue key containing sessionId and timestamp. Correct key retains product/tenant/response variation while removing unrelated request identity.'},
      {q:'Cache-aside, write-through aur write-behind kab use karein?',analogy:'Counter copy missing ho toh godown se lao: cache-aside. Sale ke saath ledger aur counter update karo: write-through pattern. Pehle counter par promise, ledger baad mein: write-behind; crash mein uncommitted promise lose ho sakta hai.',body:wrap('<table><tr><th>Pattern</th><th>Flow</th><th>Trade-off</th></tr><tr><td>Cache-aside</td><td>GET→miss→DB→cache TTL</td><td>Lazy population; miss/freshness handling</td></tr><tr><td>Write-through</td><td>Write path synchronously updates store/cache</td><td>More write work; partial failure handling</td></tr><tr><td>Write-behind</td><td>Cache/queue acknowledgement before origin persistence</td><td>Durable queue/order/retry/loss design required</td></tr></table>'),points:['Practical item-cache write path: commit DB write, then invalidate matching cached item; next read refills. DB commit and invalidation are not one distributed transaction. A crash or a concurrent old refill can leave stale data. Version fencing/change events/repair plus bounded TTL reduce risk.','A strong origin GetItem does not make cache hits strongly consistent. Source replica lag and an old in-flight read can add data age. Query cache invalidation is harder than one item key because many result sets may include the changed row.','Write-through can populate unread keys and cannot remove every partial failure without a defined protocol. Durable Valkey logging protects the cache write within its contract; it does not automatically commit an unrelated RDS write. Checkout invariants still need an authoritative atomic design.'],asli:'Action: host test first proves stale499 after DB update599 without invalidation, then correct599 after invalidate/refill. Another test discards an in-flight old fill after a concurrent update; no global strong-consistency claim.'},
      {q:'TTL, eviction aur stampede kaise control karun?',analogy:'Catalogue copy ka expiry sticker freshness window hai. Shelf full ho toh older copy evict hoti hai. Sale ke time same copy expire ho aur200customers godown bhaagein toh thundering herd banta hai.',body:'<p>TTL limits entry residency, not correctness of an already-stale origin result. Eviction removes entries under memory policy, often before TTL. Negative caching can reduce repeated missing-key calls but can hide a newly created item until short TTL/invalidation.</p>',points:['Spread different key expirations with jitter; keep the maximum freshness budget explicit. One hot key still needs request coalescing: one caller refills, others wait briefly or follow a reviewed stale-while-revalidate policy.','Per-process locks coordinate only that process. Distributed lock leases/version fencing, deadlines and bounded retries need review across a fleet. A lock that expires before refill completes can allow multiple owners; never promise exactly-one global refill from a simple SETNX recipe.','Cache down? Bound origin fallback concurrency/rate, use circuit-breaker/deadline/load shedding and test the cold-cache event. noeviction returns memory errors rather than reclaiming keys; durable mode does not disable TTL or eviction.'],asli:'Action: lab coalesces20 requests into one actual origin read, enforces entry-count LRU, tests short negative TTL and errors. Planner models200simultaneous cold requests; choosing a longer TTL alone does not fix that expiry burst.'},
      {q:'Valkey, Redis OSS, Memcached aur durable primary mein kya choose karun?',analogy:'Counter shelf, sorted score-board aur durable branch ledger alag needs hain. Product name se durability assume mat karo; exact deployment and acknowledgement contract choose karo.',body:wrap('<table><tr><th>Need</th><th>Candidate</th><th>Review</th></tr><tr><td>General cache; sorted sets/sessions</td><td>ElastiCache Valkey/Redis OSS</td><td>Features/client, HA, eviction and persistence mode</td></tr><tr><td>Simple key/value cache</td><td>Memcached candidate</td><td>Node-based sharding lacks replicated durable state</td></tr><tr><td>Durable in-memory primary</td><td>MemoryDB or eligible durable Valkey 9.0+ ElastiCache</td><td>Exact durability/features/Region and cost</td></tr><tr><td>Repeated eventual DynamoDB reads</td><td>DAX</td><td>Supported DynamoDB APIs and stale windows</td></tr></table>'),points:['Traditional node-based Valkey/Redis OSS replicas use asynchronous replication; failover can lose recent writes. More replicas are not proof of durable acknowledged writes. Node-based Memcached is a simple partitioned cache; current Serverless deployment has a different managed Multi-AZ architecture.','Current ElastiCache Valkey 9.0+ node-based durability persists through a Multi-AZ transactional log. Synchronous acknowledgement waits for durability; async durable mode can lose up to 10 seconds and applies backpressure if the buffer falls behind. Feature/Region/node eligibility needs checking; this course mission uses traditional8.0.','MemoryDB remains a durable in-memory database candidate. Compare supported commands, operations, durability/latency, scaling, eviction and price; “only MemoryDB durable” is stale. Leaderboard sorted sets can fit Valkey/Redis-compatible stores, with a reviewed rebuild/durability plan.'],asli:'Decision: rebuildable copy → cache design; durable primary → explicit persistence/acknowledgement contract; ranked scores → suitable sorted-set design. “Memcached is the only multithreaded option” is not a safe modern engine comparison.'},
      {q:'HA cache ka proof flags se aage kya hai?',analogy:'Building plan par “two exits” likhne se two usable exits nahi milte. Count actual exits, different failure zones aur working access route; safety sticker alone enough nahi.',body:'<p>For the traditional node-based single-shard fixture, create a primary plus replica in different AZs. Multi-AZ and automatic failover must be enabled, with ready actual members. Replication is asynchronous; clients need DNS/topology refresh, reconnect and bounded retry. Read replicas and sharded key space answer different scale questions.</p>',points:['Use private subnet group, correct VPC/SG attachment, scoped app port 6379, TLS, at-rest encryption and RBAC. Valkey API at-rest default is currently true; explicitly configure/read back the required settings. TLS encryption is not user authorization or data-correctness proof.','Cluster mode enabled splits key slots across shards and needs a compatible client; a hot single key can remain hot. This simulator models one shard/cluster mode disabled; requested nodes must actually exist before readiness. No fake protocol or failover timing is simulated.','Current ElastiCache Serverless manages scaling/replicated Multi-AZ and TLS. VPC endpoints are supported; eligible Valkey 9.0+ public endpoints require IAM authentication and TLS 1.3. Node-based private cluster requirements should not become a blanket claim that every modern deployment is VPC-only.'],code:SOLUTION.join('\n'),asli:'Action: main terminal repairs public ingress, creates two nodes with TLS/RBAC, waits, enables HA and reads actual member/AZ metadata. Moto5.2.4 shows only one member for num-cache-clusters 2 despite enabled flags; lab labels that gap instead of calling HA verified.'},
      {q:'DAX, CloudFront, API cache ya app cache?',analogy:'User ke shehar ka public brochure edge par ho sakta hai; app ke per-scope result shared shelf par. DynamoDB-specific wrapper ko SQL query accelerator samajhna wrong address hai.',body:wrap('<table><tr><th>Layer</th><th>Candidate</th><th>Boundary</th></tr><tr><td>Global public objects/responses</td><td>CloudFront</td><td>Reviewed cache key/auth/freshness</td></tr><tr><td>REST API stage response</td><td>API Gateway cache</td><td>Paid stage cache; HTTP API differs</td></tr><tr><td>General app/query/session cache</td><td>ElastiCache or in-process</td><td>Scope/expiry/eviction/failure design</td></tr><tr><td>DynamoDB eventual-read acceleration</td><td>DAX</td><td>Strong/transactional reads pass through</td></tr></table>'),points:['DAX is not an RDS accelerator. Strong reads/TransactGetItems pass through to DynamoDB and are not cached; a cached eventual read can still be stale. DAX item and query caches have distinct invalidation/TTL behavior; writes that bypass DAX can leave cached results stale.','DAX uses VPC/subnet placement, compatible client, a service-trusted scoped DynamoDB role and application IAM permissions. TLS endpoint uses9111; unencrypted endpoint8111. Three nodes across failure zones are a common HA starting point, not a guarantee of zero interruption.','Per-user response caching is possible with correct isolation, but public reuse often disappears as key cardinality grows. Choose the closest useful layer after access/freshness/privacy review; more cache layers add invalidation and debugging complexity.'],code:`aws dax create-cluster --cluster-name cart-accel --node-type dax.t3.small --replication-factor 3 --iam-role-arn ${ROLE} --subnet-group-name shop-dax-private --security-group-ids sg-cache --availability-zones ap-south-1a ap-south-1b ap-south-1c --sse-specification '{"Enabled":true}' --cluster-endpoint-encryption-type TLS\naws dax describe-clusters --cluster-names cart-accel`,asli:'Action: interview creates a scoped three-node DAX metadata fixture for an explicitly eventual-read cart display. Checkout remains authoritative. Two simulator observations represent readiness, not an AWS duration or real TLS/auth test.'},
      {q:'Sizing, bill aur production debugging ka decision flow?',analogy:'Shelf cost ke saath stock size, active working set, copying work aur counter queue count karo. Cheap shelf with wrong catalogue is no saving; oversized shelf does not fix unique-per-request labels.',body:'<p>Approx US East public prices checked2026-10-26: Valkey cache.t4g.small $0.0256/node-hour versus Redis OSS $0.032; two Valkey nodes ×720 h ≈$36.86/month gross. Valkey Serverless $0.084/GB-hour with100 MB minimum plus $0.0000000023/ECPU ($0.0023/million). Other serverless engines have1 GB minimum; CPU/bytes-heavy commands consume more ECPU.</p>',points:['Serverless 500 GET/s ×2 ECPU ×30 days ≈$5.96 ECPU plus approx $6.05 minimum storage, before fills/invalidations/network/extras. This is illustrative request arithmetic, not an invoice or equal-performance node comparison. New durable sync mode has separate pricing; do not apply traditional8.0 rates/features blindly.','Galti jo sab karte hain: price by logical data bytes without overhead/fragmentation/replicas; use replica/cache as authoritative stock; omit scope from key; set no TTL then hope eviction creates freshness; assume a cache outage makes unlimited DB fallback safe.','Production me kya hota hai: keys churn, eviction storms, large values block work, cold deploys stampede origin, replicas lag, stale fills race invalidation and retries overload the DB. Monitor hits/misses, evictions, memory/CPU/network, replication lag, origin QPS, errors and p95/p99 together.','Interview follow-ups: which response variations belong in key? What if DB commit succeeds and invalidation fails? How coordinate refills across instances? What survives all cache nodes failing? Who owns freshness and checkout correctness?'],asli:'Decision tree: reuse exists? no → fix query/key first; freshness acceptable? no → authoritative path; public/global → edge candidate; general app cache → Valkey/Memcached as requirements fit; eventual DynamoDB reads → DAX candidate; durable primary → reviewed MemoryDB/eligible durable Valkey option. Size from measured working set and failure load.'}
    ],
    myth:[{myth:'“Hit ratio high hai, data automatically correct hai.”',sach:'Scope, source age, invalidation and authoritative checkout invariants matter. Wrong-tenant or stale stock at 99% hits is still a bug.'},{myth:'“Multi-AZ enabled flag means two usable cross-AZ nodes exist.”',sach:'Inspect actual members, roles, AZs and readiness. Moto flag/member mismatch is explicitly documented; no real failover/TLS proof.'},{myth:'“TTL solves every expiry burst; one local lock coordinates the fleet.”',sach:'Jitter spreads different keys; hot-key coalescing needs a reviewed scope/lease/fencing design, deadlines and protected origin capacity.'},{myth:'“All ElastiCache is ephemeral; durable mode prevents eviction.”',sach:'Current eligible Valkey 9.0+ has explicit durability options. TTL/eviction policy still applies; MemoryDB is another durable-primary candidate.'}],
    playbook:{title:'Cache kab aur kahan — correctness pehle',use:['Repeated expensive catalogue/query reads with accepted freshness/privacy scope','Sorted sets/session designs with deliberate expiry, rebuild and persistence contract','DAX for suitable eventual DynamoDB reads; edge/API layer when response sharing fits'],avoid:['Authoritative checkout stock/price inferred from stale cache or lagging replica','Key scope removed to inflate hits; request IDs added without response variation','Unbounded retries/fallback or unreviewed write-behind for money/inventory'],how:['Name reusable response, authorized scope and freshness budget','Choose strategy/layer and explicit invalidation/fill failure protocol','Measure working set/overhead, cache and origin peak load, then full cost','Inspect real members/AZs/security settings; exercise cold cache, failure and data races'],redflags:['High key cardinality per request; low reuse despite bigger node','HA flag without ready replica in another AZ','Strong origin read called strong cached response','Durability assumed to prevent TTL/eviction or persist unrelated DB effects'],rule:'Reuse/scope → freshness/invariants → strategy/layer → bounded refill/failure → measured sizing/cost and actual data proof.'},
    exam:[{cue:'"repeated DB reads; general app cache"',pick:'ElastiCache candidate',why:'Validate data reuse, freshness, keys and protected origin fallback.'},{cue:'"DynamoDB eventual reads; microsecond acceleration"',pick:'DAX',why:'Strong/transaction reads pass through; client/VPC/IAM and stale windows matter.'},{cue:'"ranking / leaderboard"',pick:'Valkey/Redis-compatible sorted set candidate',why:'Review rebuild/durability and hot key; one gameId partition plus DAX is not universal.'},{cue:'"session outside app instance"',pick:'Reviewed shared state store',why:'ElastiCache/DynamoDB or appropriate durable option; expiry/revocation/availability still required.'},{cue:'"durable in-memory primary"',pick:'MemoryDB or eligible durable Valkey 9.0+ ElastiCache',why:'Select exact persistence acknowledgement/features, not an obsolete service-name-only rule.'},{cue:'"simple node-based key/value cache"',pick:'Memcached candidate',why:'No rich sorted-set/replication requirement; serverless deployment differs.'},{cue:'"hot key expires; origin spikes"',pick:'Coalescing plus TTL jitter and bounded fallback',why:'Jitter alone cannot coordinate simultaneous requests for the same key.'},{cue:'"global public response / REST API stage"',pick:'CloudFront / API Gateway cache',why:'Cache key/auth/freshness reviewed; HTTP API feature set differs.'},{cue:'"Multi-AZ cache needed"',pick:'Actual ready cross-AZ primary/replica plus automatic failover',why:'Control-plane flag is not node placement or real failover proof.'}],
    stages:[
      {type:'dryrun',title:'🔬 Cold miss, price update aur refill herd',goal:'Har click par data owner aur origin calls dekho. Three inline decisions mein freshness/scope/refill contract choose karo.',nodes:[N('app',150,255,{label:'Catalogue API'}),N('cache',500,125,{label:'Scoped cache'}),N('rds',850,255,{label:'Origin DB'})],edges:[{from:'app',to:'cache'},{from:'cache',to:'rds'},{from:'app',to:'rds',dashed:true}],panels:[{id:'data',title:'Data / freshness'},{id:'load',title:'Origin / refill'}],steps:[
        {say:'Catalogue API requests shop/kurta. Stable response-scope key is absent. One leader reads the origin; cache miss is normal and must have a bounded path.',flows:[{from:'app',to:'cache',label:'GET',tone:'slow'},{from:'cache',to:'rds',label:'miss',tone:'slow'}],nodes:{cache:{tone:'idle',badge:'cold'},rds:{tone:'busy',badge:'1 actual read'}},panels:{data:['Key: catalogue schema + authorized tenant + product','Origin returns 499/version 1'],load:['Local lab1 cold request→1 DynamoDB GetItem','Course workload40 SQL queries per cold page is a separate fixture']}},
        {say:'Cache stores a copy with 60 s TTL. Repeated same-scope catalogue reads hit the copy. Checkout still validates authoritative price/stock.',flows:[{from:'app',to:'cache',label:'hit',tone:'ok'}],nodes:{cache:{tone:'ok',badge:'499/v1;TTL 60'}},panels:{load:['Local lab10 requests→1 origin read+9 hits','A cache hit does not prove current stock']},ask:Q('Where should checkout enforce price and available-stock invariants?','Use the authoritative transaction path; cached catalogue has an accepted stale window',['Use the catalogue cache alone because high hit ratio makes every result strongly current','Use a lagging read replica alone because replicas acknowledge every primary transaction','Use the oldest in-process session copy because TTL guarantees the original price forever'],0,'Authoritative transaction preserves invariants. Cache hits are not strong consistency; asynchronous replicas may lag; session copies/TTL do not enforce stock or immutable prices.')},
        {say:'Origin commits599/version 2. Without invalidation, cache may still return499. Commit then invalidate item key; next miss refills. The two operations are not a distributed transaction.',nodes:{rds:{tone:'new',badge:'599/version 2'},cache:{tone:'slow',badge:'old499 until repair'}},panels:{data:['A strong origin read does not make later cache hits strong','Source lag/in-flight fills can add data age']},ask:Q('What is missing from a DB-write-plus-cache-invalidate design?', 'Review partial failures and stale in-flight fills; use bounded freshness/repair/versioning',['Assume the two calls are atomic because both are executed by the same app process','Invalidate before writing and assume no concurrent reader can repopulate old bytes','Give the entry no TTL because eviction will remove stale data at the exact business deadline'],1,'DB/cache calls are not atomic. Pre-write invalidation can race old fills; TTL/repair/version fencing need review. Eviction is memory policy, not a precise freshness deadline.')},
        {say:'A test gate pauses old data before publication. DB commits699/version 3 and invalidation marks the fill obsolete. Reference cache discards the old fill and refetches.',flows:[{from:'cache',to:'rds',label:'refetch',tone:'ok'}],nodes:{cache:{tone:'new',badge:'publish699/v3'}},panels:{data:['Actual host race:2 origin reads, final699/version 3','Single-process coordination only; no fleet-wide lock claim']}},
        {say:'Two hundred requests see a cold hot key at once. TTL alone sends a herd to origin; coalescing lets one leader refill within a bounded coordination scope.',nodes:{cache:{tone:'busy',badge:'cold hot key'},rds:{tone:'slow',badge:'overload risk'}},ask:Q('Best scoped protection for simultaneous expiry requests?', 'Coalesce refills with deadlines, protect origin capacity and spread other key expirations',['Increase TTL alone and assume every future cold deployment or key eviction disappears','Add the request timestamp to each key so all requests can independently cache a result','Allow unlimited DB fallback so cache failures never need retry or load-shedding limits'],2,'Coalescing/deadlines and bounded fallback protect the origin; jitter spreads different keys. Longer TTL cannot remove all cold events; timestamps destroy reuse; unlimited fallback can take down the DB.')},
        {say:'Host lab20 concurrent requests use one real origin read with19 coalesced followers. Managed cache HA/TLS metadata is a separate acceptance check, not proof of the host refill or AWS performance.',nodes:{cache:{tone:'ok',badge:'1 leader+19 waiters'},rds:{tone:'ok',badge:'1 origin read'}},panels:{load:['Counts from controlled concurrency, not RPS/p99 benchmark','Local cache is not a Valkey/DAX server'],data:['Source tenant/product/version checked','No wrong-tenant or stale-fill publication accepted']}}
      ],lesson:'Cache only reusable scoped responses. Authoritative invariants, invalidation races and bounded cold/failure load stay explicit.'},
      {type:'flowlab',title:'🎛️ Hit ratio, DB load aur cache freshness',goal:'Keep at least 1000 catalogue reads/s and 3 writes/s. Stable scoped key, enough usable cache budget, TTL≤60 s and coalesced refill choose karo. Try TTL 60,4 MiB,stable key,coalesced refill.',scenario:'Declared model:1000 uniform products,2 KiB value ×1.5 memory overhead;40 origin SQL queries per miss. Uniform Poisson reads/writes and fresh instant origin assumed. Writes invalidate matching items. Source lag/races/failure age are excluded; TTL here is modeled cache residency, not a production end-to-end freshness guarantee.',knobs:[
        {id:'reads',label:'Catalogue reads',min:500,max:1500,step:500,value:1000,fmt:n=>n+' /s'},
        {id:'writes',label:'Catalogue updates',min:1,max:5,step:2,value:3,fmt:n=>n+' /s'},
        {id:'ttl',label:'TTL maximum',min:10,max:90,step:10,value:10,unit:' s'},
        {id:'memory',label:'Usable fixture budget',min:1,max:4,step:1,value:1,unit:' MiB'},
        {id:'key',label:'Key design',min:0,max:1,step:1,value:0,labels:{0:'Per-request',1:'Stable scope'}},
        {id:'refill',label:'Cold hot-key refill',min:0,max:1,step:1,value:0,labels:{0:'200 leaders',1:'Coalesced'}}
      ],model:k=>{const p=plan(k);return {readouts:[{label:'Modeled hit ratio',value:(p.hit*100).toFixed(1)+'%',tone:p.hit>=.95?'ok':'bad'},{label:'Origin read queries',value:Math.round(p.db)+' queries/s',tone:p.db<=1000?'ok':'bad'},{label:'TTL residency window',value:k.ttl+' s · fresh-origin model',tone:k.ttl<=60?'ok':'bad'},{label:'Cold burst origin calls',value:p.burst+' for 200 requests',tone:p.burst===1?'ok':'bad'},{label:'Serverless gross/month',value:'approx $'+p.serverless.toFixed(2),tone:'acc'},{label:'Two small nodes gross/month',value:'approx $'+p.nodes.toFixed(2),tone:'acc'}],verdict:{ok:p.ok,text:p.ok?'Required load retained; modeled hits≥95%,origin queries≤1000/s,TTL≤60 s and coalesced refill. Validate source age, distributed coordination and real memory/latency before production.':k.reads<1000||k.writes<3?'Required read/write traffic cannot be reduced to win.':!k.key?'Per-request key removes reuse. Retain response scope; remove unrelated request identity.':k.ttl>60?'Longer TTL violates the declared display freshness budget.':p.capacity<1?'Working set does not fit the declared usable memory budget; real sizing also needs measured overhead.':!k.refill?'A cold hot key still sends200origin requests. Longer TTL does not fix the herd.':'Compare hit ratio/origin load with the60second budget. Capacity, expiry and writes all affect reuse.'}};},check:k=>plan(k).ok,lesson:'Teaching renewal model: expected item lifetime=min(TTL,next write), with uniform reads and entry-budget fraction. Serverless estimate includes 2 ECPU per 2 KiB GET/fill plus 1 per invalidation,100 MB minimum storage; approximate US East rates from 2026-10-14 catalog. Two-node $36.86 is compute-only. Excludes source DB, real CPU weights, network, backup, credits and tax; virtual1..4 MiB budget is not a purchasable node size.'},
      {type:'bins',title:'🗂️ Key scope — public catalogue contract',instructions:'Fixture response varies by authorized tenant, product, locale/currency and schema version. Public response does not vary by session or request timestamp. Private/discount responses need their own reviewed scope.',bins:[{id:'include',label:'Include in this key'},{id:'exclude',label:'Exclude for this public response'}],items:[{text:'Authorized tenant',bin:'include',explain:'Tenant is a response/isolation boundary; derive authorized scope separately.'},{text:'Product ID',bin:'include',explain:'Different products have different data.'},{text:'Locale/currency when response differs',bin:'include',explain:'Include dimensions that change displayed values.'},{text:'Stable schema/deployment version',bin:'include',explain:'Prevent reading incompatible old representations.'},{text:'Unrelated per-request timestamp',bin:'exclude',explain:'A new timestamp on every request destroys reuse without changing this public response.'},{text:'Session ID for identical public catalogue',bin:'exclude',explain:'No session variation in this fixture; personalized responses need appropriate authorization scope.'}]},
      {type:'match',title:'🔗 Control ka purpose',instructions:'Mechanism ko matching contract se pair karo.',pairs:[{left:'TTL',right:'Bounded entry residency; source freshness still matters',explain:'Expiry is not a transaction or guarantee that source data was new.'},{left:'Request coalescing',right:'One refill leader within the coordination scope',explain:'Per-process coalescing does not coordinate an entire fleet.'},{left:'Invalidate after DB commit',right:'Remove matching copy; handle the non-atomic gap',explain:'Write failure and stale in-flight refill still need review.'},{left:'Eviction policy',right:'Memory-pressure behavior, independent of freshness intent',explain:'Durability does not automatically disable eviction/TTL.'},{left:'DAX strong read',right:'Pass through to DynamoDB; not served from cached item',explain:'DAX acceleration targets eligible eventual reads.'},{left:'Multi-AZ flag',right:'Configuration to verify against actual ready nodes/AZs',explain:'Flags alone cannot prove real HA/failover or TLS/network behavior.'}]},
      {type:'triage',title:'🩺 Hit ratio20%: node chhota ya key galat?',symptom:'Course telemetry shows200 hits and800 misses for 1000 public catalogue requests. Same tenant/product/currency repeat, yet key cardinality grows per request. No real AWS/Moto metric capture is claimed.',goal:'Sample keys aur workload proof inspect karo, phir root cause and safe repair choose karo.',commands:[
        {cmd:'aws logs tail /shopkaro/catalog-key-samples',out:'tenant=shop product=kurta currency=INR key=catalog:shop:kurta:INR:session-18:ts-101\ntenant=shop product=kurta currency=INR key=catalog:shop:kurta:INR:session-21:ts-102\nresponseScope=public; responseBytesIdentical=true',clue:true,note:'Unrelated session/timestamp change keys for the identical public response.'},
        {cmd:'aws logs tail /shopkaro/catalog-cache-summary',out:'requests=1000 CacheHits=200 CacheMisses=800 OriginReads=800\nuniqueResponseScopes=20 uniqueCacheKeys=820',clue:true,note:'Compare response cardinality with key cardinality before buying memory.'},
        {cmd:'aws elasticache describe-cache-clusters --cache-cluster-id catalog-cache-001 --show-cache-node-info',out:'{"CacheClusters":[{"Engine":"valkey","CacheClusterStatus":"available","CacheNodeType":"cache.t4g.small"}]}',clue:false,note:'A ready node/type does not prove correct keys, memory headroom or data freshness.'}
      ],questions:[
        Q('What most directly explains the sampled low reuse?', 'Session/timestamp fragments identical public responses into per-request cache entries',['TLS encryption automatically changes every catalogue value into a different product response','Multi-AZ promotion requires each request to use a new random cache key for correctness','A second replica removes all possible hit ratio effects from application key design'],0,'Sampled key variation exceeds response scope. TLS does not change logical response identity; HA does not require random keys; replicas cannot repair per-request keys.'),
        Q('Which repair keeps response isolation while improving reuse?', 'Keep tenant/product/currency/schema scope; remove unrelated session/timestamp dimensions',['Remove tenant and currency from every key because a shared product ID is always enough','Keep the request timestamp and increase node size until each request becomes a repeat hit','Trust high hit ratio alone and skip checking cached price or authorization after the change'],1,'Retain actual response/authorization variation. Removing tenant/currency can leak wrong data; bigger memory cannot reuse never-repeated keys; validate data/freshness after any key change.')
      ]},
      {type:'terminal',title:'🖥️ Private catalogue cache — actual readiness',instructions:'Network/subnet/RBAC fixtures already exist. Two small nodes fit approx $36.86/month gross compute; budget forbids extra/larger nodes. Scope is control-plane readiness, not GET/SET or measured failover.',goal:'<p><b>1 — Network:</b> revoke sg-cache TCP 6379 from 0.0.0.0/0, then authorize TCP 6379 only from sg-app. Preserve app SG and all DB/cart data.</p><p><b>2 — Create:</b> catalog-cache, Valkey 8.0, cache.t4g.small, num-cache-clusters 2, AZ-a/b; shop-cache-private subnet group, sg-cache, TLS/at-rest encryption and catalog-app RBAC group. Wait replication-group-available.</p><p><b>3 — Enable HA:</b> modify-replication-group with automatic failover +Multi-AZ and apply-immediately; wait readiness again. Correct initial HA flags are also a valid real configuration.</p><p><b>4 — Inspect:</b> describe-replication-groups must return current available group, actual primary+replica across AZ-a/b, correct permissions/encryption. Empty waiter output or enabled flags alone is insufficient.</p>',account:seed(),tasks:TASKS,solution:SOLUTION,hints:['Inspect existing subnet/SG/RBAC fixture; TLS is not authorization, and HA needs actual cross-AZ replica.',SOLUTION.slice(0,2).join(' phir '),SOLUTION.slice(2,4).join(' phir '),SOLUTION.slice(4).join(' phir ')],success:AG.allOf(TASKS),successText:'Private port scoped to app SG; original data preserved; two-node Valkey fixture is ready across two AZs with encryption/RBAC and HA. Current actual member readback agrees. No cache hit, packet, IAM/TLS runtime or failover-duration proof was claimed.'},
      {type:'docker',title:'🐳 Lab16 — real origin counts and data races',project:'16-cache-aside',goal:'Run host cache-aside data/count tests and inspect actual managed-cache API gaps on owned ephemeral Moto servers.',why:'Host data/race proof and managed service metadata answer different questions. Docker Valkey follow-up is pending installation, not represented as completed runtime.',steps:[{text:'Read cache.py/test_cache.py; run actual origin read, invalidation and concurrency tests.',cmd:'source ../env.sh && ../.venv/bin/python -I test_cache.py',expect:'34 behavior checks;10reads→1 origin+9 hits;20 concurrent→1 origin+19 coalesced;in-flight race returns699/version 3. Owned tables[]/server stopped.'},{text:'Run metadata probe on another owned ephemeral server; inspect limits instead of declaring HA from flags.',cmd:'../.venv/bin/python -I metadata.py',expect:'num-cache-clusters 2 produces only one Moto member; unsupported APIs documented. Own listener closed, no shared reset.'},{text:'Read Docker follow-up in README after Docker is available; it is unverified here.',expect:'Do not infer Valkey/DAX runtime, real TLS/HA or AWS performance from the host cache or metadata.'}],observe:Q('What did lab16 actually verify?', 'Host cache data/count/race behavior; managed cache metadata has explicit emulator gaps',['A successful real Valkey container and managed TLS failover completed within a measured SLA','Every Multi-AZ enabled flag corresponded to two live cache members in different AZs','Strong origin reads made all subsequent cached results globally strongly consistent'],2,'Host reads and controlled races are actual evidence. Docker/managed TLS/failover were not run; Moto returned one member despite flags; caching retains its own stale window despite strong source reads.')},
      {type:'quiz',title:'🎓 Cache trade-offs and failure contracts',questions:[
        Q('Public product response is identical across sessions, but tenant/currency differ. Key strategy?', 'Keep tenant/product/currency/schema scope; omit unrelated per-request session/timestamp',['Keep product alone and assume tenant or currency never affects cache isolation requirements','Append a random request ID so every request can safely reuse the same stored public response','Use one constant key because identical route paths guarantee identical authorized payloads'],0,'Key must match actual response scope. Product alone drops tenant/currency; random request ID destroys reuse; one constant key ignores authorization and response variation.'),
        Q('DB write succeeds, then cache invalidation fails. Which statement is accurate?', 'Cache can remain stale; use bounded freshness, repair/change events and race-aware design',['The DB write automatically rolls back because cache and database share a transaction boundary','A longer cache TTL forces every existing entry to observe the successful DB update immediately','Read replicas make the stale cached entry current even when the cache receives no update'],1,'DB/cache updates are not atomic. TTL/repair/change processing and in-flight fills matter; longer TTL can prolong staleness; replicas do not update an independent cache automatically.'),
        Q('A hot key expires during a large burst. Suitable protection?', 'Coalesce refill with deadlines/fencing scope; add jitter and bounded origin fallback',['Only increase memory, because physical node size guarantees one refill for every cache key','Only extend TTL, because expiration, eviction and cold deployment cannot occur afterward','Allow each caller to retry the DB without a limit so every missed request gets a fresh copy'],2,'Coalescing plus protected origin and jitter addresses failure load. Memory/TTL alone do not prevent all cold events; unlimited retries amplify the herd. Fleet coordination needs explicit scope/leases/fencing.'),
        Q('DynamoDB-backed view requires strong or transactional reads. DAX implication?', 'Those reads pass through to DynamoDB and are not accelerated from the cached item',['Strong reads are served from the DAX item cache after enabling Multi-AZ on the cluster','DAX converts RDS SQL transactions into DynamoDB transactions through its role automatically','DAX never needs a compatible client or VPC path because every endpoint is a public HTTP API'],3,'DAX caches eligible eventual reads; strong/transaction reads pass through. Multi-AZ does not make cache strong; DAX is not an RDS translator; DAX needs compatible client and VPC/IAM connectivity.'),
        Q('Need durable in-memory primary storage. Current decision guidance?', 'Compare MemoryDB with eligible durable Valkey 9.0+ options and exact write/eviction contracts',['Assume every ElastiCache node is ephemeral because managed caches can never persist writes','Treat any replica as durable acknowledgement because asynchronous replication cannot lose data','Choose no TTL and assume memory-pressure eviction can no longer remove application keys'],0,'Current Valkey 9.0+ supports configured Multi-AZ-log durability; MemoryDB remains a candidate. Async replicas can lose recent writes; no TTL does not by itself prevent memory-policy eviction.'),
        Q('Why inspect members/AZs after enabling managed cache HA flags?', 'Actual ready primary/replica placement is required; enabled flags alone are insufficient',['Member count is irrelevant because a single node automatically supplies a separate standby AZ','A successful describe response proves all TLS, IAM and network requests were exercised end-to-end','Every simulator waiter measures the exact AWS failover duration for the production workload'],1,'Ready actual cross-AZ members matter. One node is no replica; metadata does not execute TLS/IAM/packets; simulator waiters represent state, not timing or a production failure drill.'),
        Q('A cache has high hit ratio but returns old catalogue after a source replica lag. Interpretation?', 'Hits measure reuse; source age plus TTL/fill behavior still determines freshness',['High hit ratio proves source replica lag cannot affect any copied catalogue value','Strong reads on another unrelated table force every existing cache entry to refresh immediately','Eviction policy uses business timestamps to guarantee entries disappear exactly at expiry'],2,'Reuse is not freshness. Lagging source can populate old data; unrelated strong reads do not invalidate cache; eviction is memory management, not business-time enforcement.'),
        Q('ElastiCache node versus serverless cost comparison needs what?', 'Measured storage/CPU or ECPU activity, replicas, minimums and complete equal-requirement cost',['Only raw object bytes, because fragmentation, commands and replicas never affect memory or cost','Only node hourly rate, because serverless has no minimum storage or request processing charges','Only correct engine name, because every Region and durability mode has identical pricing'],3,'Compare equal requirements using actual memory/command/load/cost meters. Raw bytes miss overhead/replicas; serverless has minimums/ECPUs; Region/engine/durability choices can change prices.')
      ]}
    ],
    interview:{title:'Interview — freshness, failure and cache choice',instructions:'Four decisions ke baad eventual cart-display DAX fixture ko actual ready metadata tak create/inspect karo.',questions:[
      Q('Interviewer: “Origin GetItem is strong, therefore cached hits are strong too?”', 'No; cached copies have their own age/invalidation contract despite a strong source read',['Yes; the first strong read permanently upgrades every future cached copy to strong consistency','Yes; TTL only affects memory usage and cannot change the correctness of a cached response','No; the only fix is to remove tenant scope so all callers read exactly the same cached bytes'],3,'Strong origin read applies at that read time. Later cache hits can be stale; TTL does affect stale windows; removing tenant scope creates a privacy/data bug rather than consistency.'),
      Q('A catalogue cache is down during peak. What should fallback protect?', 'Origin capacity using bounded concurrency, deadlines/backoff and deliberate load shedding',['Hit ratio only, because cache downtime cannot change origin request count or queueing','All requests with unlimited retries, because retrying always reduces downstream load','Cache process uptime only, because stale checkout stock is safe until the cache recovers'],0,'Fallback can move a herd to DB. Bound work and deadlines; hit ratio/uptime alone miss origin overload and data correctness; unlimited retries amplify failure; stock still needs authoritative checks.'),
      Q('Does a per-process lock establish one refill across a multi-instance fleet?', 'No; coordination scope, lease expiry, version fencing and retry deadlines need design',['Yes; every app instance shares the same Python lock merely by connecting to one database','Yes; a longer TTL prevents all deployment, eviction and outage-related cold misses','No; every caller must use a unique key because distributed caches cannot share results'],1,'Local lock scope is one process. Shared origin does not share a lock; TTL cannot eliminate all cold events; unique keys destroy reuse. Distributed coordination must handle expiry/old owners.'),
      Q('Catalogue runs on RDS; repeated eventual cart views run on DynamoDB. Cache candidates?', 'General scoped cache for RDS; DAX candidate for eligible eventual DynamoDB views',['DAX automatically translates the RDS catalogue SQL and transaction history into cached items','One public constant CloudFront key can safely share every private cart across all customers','Any read replica makes checkout stock and every cached price instantly globally authoritative'],2,'General cache can wrap RDS; DAX is DynamoDB-specific with eligible eventual reads. DAX does not translate SQL; private cart keys/auth cannot be public constant; replicas/cache are not authoritative global checkout state.'),
      {terminal:(()=>{const a=seed();a.securityGroups[1].ingress=[{protocol:'tcp',fromPort:9111,toPort:9111,sourceGroup:'sg-app'}];const create=`aws dax create-cluster --cluster-name cart-accel --node-type dax.t3.small --replication-factor 3 --iam-role-arn ${ROLE} --subnet-group-name shop-dax-private --security-group-ids sg-cache --availability-zones ap-south-1a ap-south-1b ap-south-1c --sse-specification '{"Enabled":true}' --cluster-endpoint-encryption-type TLS`,describe='aws dax describe-clusters --cluster-names cart-accel';
        const find=s=>(s.account.daxClusters||[]).find(g=>g.id==='cart-accel');const tasks=[{text:'Original data/network/role preserved; port 9111 restricted to app SG',check:s=>preserve(s)&&privateRule(s,9111)&&(s.account.cacheGroups||[]).length===0},{text:'Actual DAX fixture has3 available nodes across3 AZs, scoped DynamoDB role, TLS/SSE',check:s=>{const g=find(s);return !!g&&s.account.daxClusters.length===1&&g.status==='available'&&g.nodeType==='dax.t3.small'&&g.roleArn===ROLE&&g.subnetGroup==='shop-dax-private'&&g.vpcId==='vpc-shop'&&g.securityGroupIds.length===1&&g.securityGroupIds[0]==='sg-cache'&&g.tls&&g.sse&&g.nodes.length===3&&g.nodes.every(n=>n.status==='available')&&new Set(g.nodes.map(n=>n.az)).size===3;}},{text:'Final current result reports available 3 nodes and encrypted endpoint 9111',check:s=>{const g=find(s),r=s.cacheRead?.service==='dax'&&s.cacheRead.groups.find(r=>r.id==='cart-accel');return !!g&&!!r&&r.revision===g.revision&&r.record.Status==='available'&&r.record.ActiveNodes===3&&r.record.ClusterDiscoveryEndpoint.Port===9111;}}];
        return {title:'🖥️ DAX for eventual cart display',goal:'<p>VPC/subnet/SG and scoped DAX-trusted read role already exist. Checkout remains authoritative; only this noncritical display accepts eventual cached reads. Create cart-accel with dax.t3.small, replication-factor 3, shop-dax-private, sg-cache, AZ-a/b/c, TLS endpoint and SSE.</p><p>Run describe-clusters after creation; fixture first response remains creating. Poll again until actual three nodes are available. Two deterministic observations are a teaching transition, not an AWS delay guarantee. Wrong role, plaintext endpoint, one-node cluster or deleted source cannot qualify.</p>',account:a,tasks,solution:[create,describe,describe],hints:['DAX targets eligible eventual DynamoDB reads; read role, private path and encrypted endpoint are separate controls.',create,describe+' phir '+describe],success:AG.allOf(tasks),successText:'Three-node DAX metadata fixture is ready across3 AZs, with scoped role and TLS/SSE endpoint metadata. No actual DAX protocol, IAM/TLS runtime, cache hit, strong-read acceleration or failover test was claimed.'};})()}
    ]},
    success:['Response scope aur accepted stale window define kar sakta hoon','Cache-aside/invalidation race, expiry herd aur protected fallback explain kar sakta hoon','Valkey/Memcached/DAX/edge/durable-primary candidates compare kar sakta hoon','Actual cache members/AZs/security metadata aur host data proof distinguish kar sakta hoon'],
    homework:'<p><b>Optional approved AWS sandbox only; billable.</b> Verify current Region/features/prices, budget and least-privilege access. Use own private cache/subnet/security/user groups and test actual authorized/denied client commands with TLS. Record correct scoped payload, source/cache age, hit/miss/origin counts and p95/p99 under fixed workload. Test cold start, invalidation failure, concurrent stale fill, cache outage and controlled HA failover with bounded DB fallback. Keep checkout authoritative. If using a durable-primary mode, test acknowledgement, eviction policy and recovery separately. Cleanup only owned node groups/DAX/serverless caches, snapshots, user/parameter/subnet groups, test tables, roles/logs and VPC fixtures. Docker local follow-up remains unverified until the user-installed runtime is ready; no blanket free-tier promise.</p>',
    cards:[{front:'Cache hit proves current data?',back:'No. Hit proves reuse; scope, source age, invalidation and accepted stale window determine correctness. Checkout invariants stay authoritative.'},{front:'Good cache key?',back:'Stable encoding of all response/authorization variation. Public catalogue may omit unrelated session/time; tenant/product/currency/schema scope remains.'},{front:'DB commit then invalidate atomic?',back:'No distributed atomicity. Handle crash/failure gap and stale in-flight fills with reviewed version/change/repair protocol and bounded TTL.'},{front:'TTL versus eviction?',back:'TTL bounds entry residency; eviction manages memory. Source age can exceed TTL assumptions; durability does not disable either policy.'},{front:'Hot-key expiry?',back:'Coalesce within a defined coordination scope, use jitter for other keys, deadlines/fencing and bounded origin fallback. Local lock is not fleet-wide.'},{front:'DAX strong read?',back:'Passes through to DynamoDB and is not served from cached item. DAX is not an RDS cache or automatic strong/freshness upgrade.'},{front:'HA flag enough?',back:'Inspect actual ready primary/replica, cross-AZ placement and current security metadata. Real client/failover tests are separate evidence.'},{front:'Durable in-memory choice?',back:'MemoryDB or eligible configured durable Valkey 9.0+ ElastiCache. Compare acknowledgement/features/price and eviction. Traditional8.0 replicas are async.'}]
  }]);
})();
